"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_electrical_engineering_core_de"]=window.LC_CHUNKS["university_electrical_engineering_core_de"]||{};window.LC_CHUNKS["university_electrical_engineering_core_de"][17]={"university_electrical_engineering_core_de:M17-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M17-L1 – Strahlung, Nahfeld und Fernfeld<\/h1>\n<p><strong>Kursbereich:<\/strong> M17 – Bachelor: Antennen<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlbereich<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M4&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M4-L1<\/a>, <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Feldbereiche unterscheiden, Fernfeldgrößen\nberechnen und lineare Polarisation beschreiben.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Von der Leitung zum offenen Raum<\/h2>\n<p>Eine Leitung führt elektromagnetische Energie entlang ihrer\nGeometrie. Eine Antenne koppelt einen Teil der Leistung in frei\npropagierende elektromagnetische Wellen ein. Beim Empfang läuft die\nKopplung in umgekehrter Richtung. Zeitveränderliche Ladungen und Ströme\nbestimmen die Felder; eine statische Ladungsverteilung allein erzeugt\nkeine kontinuierliche Abstrahlung. Das statische Feld, gespeicherte\nreaktive Energie und abgestrahlte Energie sind verschiedene Aspekte\ndesselben Feldmodells.<\/p>\n<p>Für eine harmonische Welle im homogenen Vakuum gelten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mrow><msub><mi>μ<\/mi><mn>0<\/mn><\/msub><msub><mi>ϵ<\/mi><mn>0<\/mn><\/msub><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">c=1/\\sqrt{\\mu_0\\epsilon_0}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mi>c<\/mi><mi>/<\/mi><mi>f<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=c/f<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mi>/<\/mi><mi>λ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">k=2\\pi/\\lambda<\/annotation><\/semantics><\/math>.\nFür die Ausbreitung in positiver z-Richtung können wir mit\nEffektivwert-Zeigern schreiben<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><munder><mi mathvariant=\"bold-italic\">𝑬<\/mi><mo accent=\"true\">_<\/mo><\/munder><mo>=<\/mo><msub><mi>E<\/mi><mn>0<\/mn><\/msub><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>j<\/mi><mi>k<\/mi><mi>z<\/mi><\/mrow><\/msup><msub><mi mathvariant=\"bold-italic\">𝒆<\/mi><mi>x<\/mi><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><munder><mi mathvariant=\"bold-italic\">𝑯<\/mi><mo accent=\"true\">_<\/mo><\/munder><mo>=<\/mo><mfrac><msub><mi>E<\/mi><mn>0<\/mn><\/msub><msub><mi>Z<\/mi><mn>0<\/mn><\/msub><\/mfrac><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>j<\/mi><mi>k<\/mi><mi>z<\/mi><\/mrow><\/msup><msub><mi mathvariant=\"bold-italic\">𝒆<\/mi><mi>y<\/mi><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\underline{\\mathbf E}=E_0e^{-jkz}\\mathbf e_x,\\qquad \\underline{\\mathbf H}=\\frac{E_0}{Z_0}e^{-jkz}\\mathbf e_y.<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>0<\/mn><\/msub><mo>≈<\/mo><mn>377<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_0\\approx377\\,\\Omega<\/annotation><\/semantics><\/math>\nist die Freiraumwellenimpedanz, nicht die Eingangsimpedanz der Antenne.\nDie zeitlich gemittelte Leistungsflussdichte ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi mathvariant=\"bold-italic\">𝑺<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">Re<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><munder><mi mathvariant=\"bold-italic\">𝑬<\/mi><mo accent=\"true\">_<\/mo><\/munder><mo>×<\/mo><msup><munder><mi mathvariant=\"bold-italic\">𝑯<\/mi><mo accent=\"true\">_<\/mo><\/munder><mo>*<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\langle\\mathbf S\\rangle=\\operatorname{Re}(\\underline{\\mathbf E}\\times\\underline{\\mathbf H}^{*})<\/annotation><\/semantics><\/math>,\nhier\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>E<\/mi><mn>0<\/mn><mn>2<\/mn><\/msubsup><mi>/<\/mi><msub><mi>Z<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">E_0^2/Z_0<\/annotation><\/semantics><\/math>\nin W/m². Bei Spitzenwert-Zeigern wäre zusätzlich der Faktor 1/2\nerforderlich.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Abstandsbereiche<\/h2>\n<p>Die Felder eines kleinen harmonischen elektrischen Dipols enthalten\nTerme, deren Beträge mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><msup><mi>r<\/mi><mn>3<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">1/r^3<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><msup><mi>r<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">1/r^2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>r<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/r<\/annotation><\/semantics><\/math>\nabfallen. Erst in großer Entfernung dominiert der Strahlungsterm\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>r<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/r<\/annotation><\/semantics><\/math>.\nFür elektrisch große Aperturen ist die Variation der Laufwege über die\nApertur entscheidend. Der Fraunhofer-Richtwert lautet<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r<\/mi><mi>F<\/mi><\/msub><mo>≈<\/mo><mfrac><mrow><mn>2<\/mn><msup><mi>D<\/mi><mn>2<\/mn><\/msup><\/mrow><mi>λ<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">r_F\\approx\\frac{2D^2}{\\lambda}.<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>D<\/mi><annotation encoding=\"application/x-tex\">D<\/annotation><\/semantics><\/math>\nist die größte relevante Abmessung. Der Ausdruck folgt näherungsweise\naus der quadratischen Wegdifferenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>r<\/mi><mo>≈<\/mo><msup><mi>D<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>8<\/mn><mi>r<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Delta r\\approx D^2/(8r)<\/annotation><\/semantics><\/math>;\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>r<\/mi><mi>F<\/mi><\/msub><annotation encoding=\"application/x-tex\">r_F<\/annotation><\/semantics><\/math>\nbeträgt die maximale zugehörige Phasenabweichung gegenüber dem\nAperturmittelpunkt etwa\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\pi/8<\/annotation><\/semantics><\/math>.\nEr ist keine universelle scharfe Grenze: Zusätzlich müssen Abstand und\nWellenlänge sowie Abstand und Antennengröße sinnvoll getrennt sein. Ein\nverbreiteter Richtwert für die innere Fresnel-Grenze elektrisch großer\nAntennen ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>62<\/mn><msqrt><mrow><msup><mi>D<\/mi><mn>3<\/mn><\/msup><mi>/<\/mi><mi>λ<\/mi><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">0{,}62\\sqrt{D^3/\\lambda}<\/annotation><\/semantics><\/math>.\nFür kleine Dipole sind andere Kriterien angemessen. Im reaktiven Nahfeld\nist das Verhältnis E/H nicht generell\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>Z<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">Z_0<\/annotation><\/semantics><\/math>;\nauch im strahlenden Nahfeld kann die Winkelverteilung noch vom Abstand\nabhängen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_062_DE.svg\"\nalt=\"Links schematische Feldbereiche um eine Apertur, rechts orthogonale E- und H-Felder einer ebenen Welle.\" />\n<figcaption>Abbildung: Die Feldbereiche einer endlichen Apertur sind\nschematisch abgegrenzt; im ebenen Fernfeldwellenmodell stehen\nelektrisches Feld, magnetisches Feld und Ausbreitungsrichtung senkrecht\nzueinander.<\/figcaption>\n<\/figure>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Polarisation und Kugelwelle<\/h2>\n<p>Die Polarisation beschreibt die zeitliche Bahn des elektrischen\nFeldvektors an einem festen Ort. Gleichphasige orthogonale Komponenten\nergeben lineare Polarisation; gleiche Beträge und 90° Phasenversatz\nergeben zirkulare Polarisation. Sonst entsteht im allgemeinen Fall eine\nEllipse. Bei zirkularer Polarisation muss die Betrachtungsrichtung für\nden Drehsinn festgelegt werden.<\/p>\n<p>Im Fernfeld breitet sich Leistung näherungsweise radial aus. Bei\nisotroper Abstrahlung gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>π<\/mi><msup><mi>r<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S=P_\\mathrm{rad}/(4\\pi r^2)<\/annotation><\/semantics><\/math>.\nEine gerichtete Quelle ändert die Winkelverteilung, nicht die\nGesamtleistung. Für ein festes Winkelintervall sinkt die Flussdichte\nquadratisch mit dem Abstand, während die Feldamplitude näherungsweise\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>r<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/r<\/annotation><\/semantics><\/math>\nfällt. Reflexionen oder Hindernisse können diese Beziehung lokal\nverändern.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Modellgrenze<\/h2>\n<p>Bei 2,4 GHz ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1249<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=0{,}1249<\/annotation><\/semantics><\/math>\nm. Eine Apertur von 0,8 m hat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r<\/mi><mi>F<\/mi><\/msub><mo>≈<\/mo><mn>10<\/mn><mo>,<\/mo><mn>25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">r_F\\approx10{,}25<\/annotation><\/semantics><\/math>\nm und eine geschätzte innere Fresnel-Grenze von 1,26 m. Bei 1 km ist die\nEntfernung für diese idealisierte Geometrie deutlich größer als beide.\nEine isotrope Quelle mit 0,01 W Strahlungsleistung erzeugt dort\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>≈<\/mo><mn>7<\/mn><mo>,<\/mo><mn>96<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>10<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">S\\approx7{,}96\\cdot10^{-10}<\/annotation><\/semantics><\/math>\nW/m² und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><\/msub><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>548<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E_\\mathrm{eff}\\approx0{,}548<\/annotation><\/semantics><\/math>\nmV/m. Diese Rechnung stellt weder eine Messung noch eine Aussage zu\nExpositionsgrenzwerten dar. Bei 0,5 m wäre ein einfaches Fernfeldmodell\nfür diese Apertur dagegen ungeeignet.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Übungen mit Lösungen<\/h2>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Wellenlänge ergibt sich bei 900 MHz? <strong>Lösung:<\/strong>\nrund 0,333 m.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Verdopple D bei unveränderter Frequenz. <strong>Lösung:<\/strong> Der\nFraunhofer-Richtwert vervierfacht sich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Was passiert mit dem isotropen Leistungsfluss bei dreifachem\nAbstand? <strong>Lösung:<\/strong> Er fällt auf 1/9, die Feldamplitude\nauf 1/3.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Wie groß ist H bei 1 V/m effektiv im ebenen Freiraumfeld?\n<strong>Lösung:<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>377<\/mn><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>65<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/377\\approx2{,}65<\/annotation><\/semantics><\/math>\nmA/m.<\/div><\/li>\n<\/ol>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://opencourses.emu.edu.tr/course/view.php?id=395\">Eastern\nMediterranean University – EENG463 Antenna Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Overview of\nElectromagnetics und Fundamental Parameters of Antennas: Strahlung und\nFeldgrößen. Kursübersicht, PDF nicht geprüft. · Zuletzt abgerufen:\n2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://vtechworks.lib.vt.edu/bitstream/handle/10919/93253/Electromagnetics_Vol2_screen-reader-friendly.pdf\">Steven\nW. Ellingson – Electromagnetics, Volume 2 (2020, VT Publishing, PDF)<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a>\n· § 9.4–9.7 und § 10.7: Strahlungs- und Fernfeldgrundlagen; kein\nvollständiger Nachweis aller Nahfeldgrenzen. · Zuletzt abgerufen:\n2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M17-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M17-L2 – Antennenparameter und Richtdiagramme<\/h1>\n<p><strong>Kursbereich:<\/strong> M17 – Bachelor: Antennen<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlbereich<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M17&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M17-L1<\/a>, <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M2&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M2-L3<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Ein Richtdiagramm integrieren, Gewinn und\nRichtwirkung unterscheiden und dBi korrekt verwenden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Richtungsabhängige Leistungsabgabe<\/h2>\n<p>Im Fernfeld ist die Strahlungsintensität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo>,<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>r<\/mi><mn>2<\/mn><\/msup><msub><mi>S<\/mi><mi>r<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">U(\\theta,\\phi)=r^2 S_r<\/annotation><\/semantics><\/math>\nin W/sr. Die Integration über den Raumwinkel liefert die abgestrahlte\nLeistung:<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mo>=<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><\/msubsup><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>π<\/mi><\/msubsup><mi>U<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo>,<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>θ<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>ϕ<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_\\mathrm{rad}=\\int_0^{2\\pi}\\int_0^\\pi U(\\theta,\\phi)\\sin\\theta\\,d\\theta\\,d\\phi.<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>θ<\/mi><annotation encoding=\"application/x-tex\">\\theta<\/annotation><\/semantics><\/math>\nist der Polarwinkel gegenüber der z-Achse,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ϕ<\/mi><annotation encoding=\"application/x-tex\">\\phi<\/annotation><\/semantics><\/math>\nder Azimut. Das Gewicht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sin\\theta<\/annotation><\/semantics><\/math>\ndarf nicht fehlen, weil ein Winkelrechteck in Polnähe weniger Raumwinkel\nabdeckt als am Äquator. Für ein normiertes Leistungsdiagramm\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo>=<\/mo><mi>U<\/mi><mi>/<\/mi><msub><mi>U<\/mi><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">x<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">F=U/U_\\mathrm{max}<\/annotation><\/semantics><\/math>\nist der Strahlraumwinkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Ω<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><mo>∫<\/mo><mi>F<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega_A=\\int F\\,d\\Omega<\/annotation><\/semantics><\/math>.\nDie maximale Richtwirkung ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>4<\/mn><mi>π<\/mi><mi>/<\/mi><msub><mi mathvariant=\"normal\">Ω<\/mi><mi>A<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">D_0=4\\pi/\\Omega_A<\/annotation><\/semantics><\/math>.\nRichtwirkung ist dimensionslos; sie vergleicht die Intensität einer\nRichtung mit dem räumlichen Mittel bei gleicher Strahlungsleistung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gewinn, Effizienz und Bezugsleistung<\/h2>\n<p>Wir unterscheiden die am Antennenanschluss angenommene Leistung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>a<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_a<\/annotation><\/semantics><\/math>\nvon der tatsächlich abgestrahlten Leistung. Mit Strahlungswirkungsgrad\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><\/msub><mi>/<\/mi><msub><mi>P<\/mi><mi>a<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\eta=P_\\mathrm{rad}/P_a<\/annotation><\/semantics><\/math>\ngilt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo>,<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>η<\/mi><mi>D<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo>,<\/mo><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>G<\/mi><mrow><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">B<\/mi><mi mathvariant=\"normal\">i<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>10<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><mi>G<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">G(\\theta,\\phi)=\\eta D(\\theta,\\phi),\\qquad G_\\mathrm{dBi}=10\\log_{10}G.<\/annotation><\/semantics><\/math><\/p>\n<p>Der realisierte Gewinn berücksichtigt zusätzlich die Fehlanpassung am\ndefinierten Eingang; diese darf in einem Linkbudget nicht ein zweites\nMal abgezogen werden. Zuleitungsverluste werden getrennt geführt, sofern\nder Bezugsort des Datenblattgewinns nicht schon vor der Leitung liegt.\ndBi referenziert einen idealen isotropen Strahler. dBd bezieht sich auf\nden idealen Halbwellendipol in seiner Hauptrichtung (rund 2,15 dBi). Ein\npassives System erzeugt keine zusätzliche Energie: Sein gerichteter\nGewinn entsteht durch Umverteilung.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Diagramm lesen<\/h2>\n<p>Der elektrisch kurze z-orientierte Dipol hat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mi>θ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">F(\\theta)=\\sin^2\\theta<\/annotation><\/semantics><\/math>.\nDas Maximum liegt bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>90<\/mn><mo>∘<\/mo><\/msup><annotation encoding=\"application/x-tex\">90^\\circ<\/annotation><\/semantics><\/math>,\nNullstellen entlang der Achse. Der Schnitt in einer Ebene mit der\nDipolachse bildet zwei gegenüberliegende Keulen; der Azimutschnitt bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>90<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=90^\\circ<\/annotation><\/semantics><\/math>\nist kreisförmig. Der 3D-Körper ist kein Kugelstrahler. Die\nHalbwertspunkte einer Hauptkeule liegen bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>45<\/mn><mo>∘<\/mo><\/msup><annotation encoding=\"application/x-tex\">45^\\circ<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mn>135<\/mn><mo>∘<\/mo><\/msup><annotation encoding=\"application/x-tex\">135^\\circ<\/annotation><\/semantics><\/math>,\ndie Halbwertsbreite beträgt 90°. In dB sind die Halbwertspunkte bei rund\n−3,01 dB. Ein Feldamplitudenverhältnis von 0,5 entspricht dagegen −6,02\ndB.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_063_DE.svg\"\nalt=\"Normiertes Dipol-Leistungsdiagramm in Polar- und kartesischer Darstellung mit Halbwertspunkten.\" />\n<figcaption>Abbildung: Das normierte Dipolmuster wird kartesisch und\npolar gezeigt; der Winkelabstand der Halbwertspunkte ergibt im\ndargestellten Schnitt eine Halbwertsbreite von 90°.<\/figcaption>\n<\/figure>\n<p>Bei einer gerichteten Antenne sind zudem Nebenkeulen, Nullstellen und\ndas Vor-Rück-Verhältnis relevant. Eine einzige Halbwertsbreite ersetzt\nkein dreidimensionales Diagramm und eine schmale Keule in nur einer\nEbene garantiert keine hohe Richtwirkung.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Integration und Zahlenbeispiel<\/h2>\n<p>Für den kurzen Dipol ergibt sich analytisch<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Ω<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>π<\/mi><\/msubsup><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>3<\/mn><\/msup><mi>θ<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>θ<\/mi><mo>=<\/mo><mfrac><mrow><mn>8<\/mn><mi>π<\/mi><\/mrow><mn>3<\/mn><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>D<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mfrac><mn>3<\/mn><mn>2<\/mn><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega_A=2\\pi\\int_0^\\pi\\sin^3\\theta\\,d\\theta=\\frac{8\\pi}{3},\\qquad D_0=\\frac32.<\/annotation><\/semantics><\/math><\/p>\n<p>Die Richtwirkung ist damit 1,76 dBi. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\eta=0{,}8<\/annotation><\/semantics><\/math>\nbeträgt der maximale Gewinn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1{,}2<\/annotation><\/semantics><\/math>\nbeziehungsweise 0,79 dBi. Werden 5 W angenommen, sind 4 W abgestrahlt\nund 1 W dissipiert. Die maximale Strahlungsintensität beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4<\/mn><mo>⋅<\/mo><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4775<\/mn><\/mrow><annotation encoding=\"application/x-tex\">4\\cdot1{,}5/(4\\pi)=0{,}4775<\/annotation><\/semantics><\/math>\nW/sr. Für einen Empfänger in 100 m Abstand ergibt sich in dieser\nRichtung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>47<\/mn><mo>,<\/mo><mn>75<\/mn><mspace width=\"0.167em\"><\/mspace><mi>μ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">47{,}75\\,\\mu<\/annotation><\/semantics><\/math>W/m².\nZur eigenen numerischen Kontrolle integriere das normierte Dipolmuster\nmit dem Raumwinkelgewicht bei 90, 180 und 360 gleich großen\nPolarwinkelintervallen (Mittelpunkte); prüfe die Annäherung an die\nanalytische Richtwirkung 1,5. Der Wirkungsgrad ist ein gewählter\nModellparameter und kein typischer Messwert für beliebige kurze\nDipole.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Übungen mit Lösungen<\/h2>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Was sind 10 dBi als lineares Verhältnis? <strong>Lösung:<\/strong>\n10.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">D_0=4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\eta=0{,}5<\/annotation><\/semantics><\/math>.\n<strong>Lösung:<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>G<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">G_0=2<\/annotation><\/semantics><\/math>,\netwa 3,01 dBi.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum wird ein Azimutschnitt eines vertikalen Dipols als\nomnidirektional bezeichnet? <strong>Lösung:<\/strong> Er ist bei festem\nPolarwinkel azimutunabhängig, nicht in allen Raumrichtungen gleich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Ein Diagramm hat Halbwertspunkte bei 20° und 50°.\n<strong>Lösung:<\/strong> 30° Halbwertsbreite in diesem Schnitt.<\/div><\/li>\n<\/ol>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://opencourses.emu.edu.tr/course/view.php?id=395\">Eastern\nMediterranean University – EENG463 Antenna Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fundamental\nParameters of Antennas-1: Richtdiagramm, Gewinn und Polarisation.\nKursübersicht, PDF nicht geprüft. · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://vtechworks.lib.vt.edu/bitstream/handle/10919/93253/Electromagnetics_Vol2_screen-reader-friendly.pdf\">Steven\nW. Ellingson – Electromagnetics, Volume 2 (2020, VT Publishing, PDF)<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a>\n· § 10.5, § 10.7–10.8, S. 173–182: Strahlungswirkungsgrad, Richtwirkung,\nGewinn und Richtdiagramm. · Zuletzt abgerufen: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M17-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M17-L3 – Dipol, Apertur und Anordnung<\/h1>\n<p><strong>Kursbereich:<\/strong> M17 – Bachelor: Antennen<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlbereich<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M17&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M17-L2<\/a>, <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Ideale Antennentypen vergleichen und den\nArrayfaktor zweier Strahler herleiten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Dipolmodelle<\/h2>\n<p>Beim idealen kurzen (Hertzschen) Dipol wird ein räumlich konstanter\nStrom auf einer sehr kleinen Länge angenommen. Sein Fernfeldbetrag ist\nproportional zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sin\\theta<\/annotation><\/semantics><\/math>.\nEin physischer dünner kurzer mittengespeister Draht hat dagegen\nnäherungsweise dreieckige Stromverteilung; insbesondere sein\nStrahlungswiderstand ist deshalb nicht mit dem des Hertzschen\nStromelements gleichzusetzen.<\/p>\n<p>Beim dünnen Halbwellendipol nutzen wir eine näherungsweise\nsinusförmige Stromverteilung. Die normierte Fernfeldamplitude wird dann\ndurch<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mrow><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><mrow><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><\/mrow><\/mfrac><\/mrow><annotation encoding=\"application/x-tex\">A(\\theta)=\\frac{\\cos[(\\pi/2)\\cos\\theta]}{\\sin\\theta}<\/annotation><\/semantics><\/math><\/p>\n<p>beschrieben, mit Grenzwert null an beiden Polen. Der normierte\nLeistungswert ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>A<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">|A|^2<\/annotation><\/semantics><\/math>.\nDer ideale dünne Halbwellendipol hat ungefähr\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>64<\/mn><\/mrow><annotation encoding=\"application/x-tex\">D_0=1{,}64<\/annotation><\/semantics><\/math>\n(2,15 dBi). Seine physische Resonanzlänge hängt von Drahtdurchmesser und\nUmgebung ab. Eine geometrisch exakt halbe Wellenlänge ist nicht generell\nbereits rein reell angepasst.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Apertur und effektive Fläche<\/h2>\n<p>Die effektive Empfangsfläche einer reziproken Antenne bei\nkonjugierter Anpassung und passender Polarisation ist<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mfrac><mrow><msup><mi>λ<\/mi><mn>2<\/mn><\/msup><mi>G<\/mi><\/mrow><mrow><mn>4<\/mn><mi>π<\/mi><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">A_e=\\frac{\\lambda^2 G}{4\\pi}.<\/annotation><\/semantics><\/math><\/p>\n<p>Sie ist eine Leistungs-Kopplungsgröße, kein unmittelbares Maß der\ngeometrischen Silhouette. Für eine große Apertur der Fläche\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>A<\/mi><mrow><mi mathvariant=\"normal\">g<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">A_\\mathrm{geom}<\/annotation><\/semantics><\/math>\nschreiben wir häufig\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><msub><mi>η<\/mi><mi>a<\/mi><\/msub><msub><mi>A<\/mi><mrow><mi mathvariant=\"normal\">g<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">A_e=\\eta_a A_\\mathrm{geom}<\/annotation><\/semantics><\/math>\nmit Aperturwirkungsgrad\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>η<\/mi><mi>a<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\eta_a<\/annotation><\/semantics><\/math>.\nDiese Beziehung ist für typische Aperturantennen nützlich, aber nicht\nals geometrische Begrenzung für jeden Drahtstrahler zu interpretieren.\nEine größere wirksame Fläche erlaubt bei gleicher Frequenz größeren\nGewinn; die Hauptkeule verengt sich bei üblicher Aperturbeleuchtung. Die\ntatsächliche Feldverteilung beeinflusst auch Nebenkeulen und\nWirkungsgrad.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zwei Elemente und Phasenlage<\/h2>\n<p>Zwei gleich starke ideale isotrope Modellquellen liegen auf der\nz-Achse bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><mi>±<\/mi><mi>d<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">z=\\pm d/2<\/annotation><\/semantics><\/math>.\nMit zusätzlicher Speisephase\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>β<\/mi><annotation encoding=\"application/x-tex\">\\beta<\/annotation><\/semantics><\/math>\nam positiven Element verwenden wir die Fernfeldkonvention<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mi>F<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>+<\/mo><msup><mi>e<\/mi><mrow><mi>j<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>k<\/mi><mi>d<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo>+<\/mo><mi>β<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo>,<\/mo><mspace width=\"1.0em\"><\/mspace><msub><mi>F<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>A<\/mi><mi>F<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><\/mrow><mn>4<\/mn><\/mfrac><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><mi>k<\/mi><mi>d<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo>+<\/mo><mi>β<\/mi><\/mrow><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">AF(\\theta)=1+e^{j(kd\\cos\\theta+\\beta)},\\quad F_n=\\frac{|AF|^2}{4}=\\cos^2\\left(\\frac{kd\\cos\\theta+\\beta}{2}\\right).<\/annotation><\/semantics><\/math><\/p>\n<p>Die gemeinsame räumliche Phase wurde weggelassen.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>F<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">F_n<\/annotation><\/semantics><\/math>\nist auf den theoretischen Spitzenwert der Summe normiert; nicht jede\nbeliebige Kombination aus d und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>β<\/mi><annotation encoding=\"application/x-tex\">\\beta<\/annotation><\/semantics><\/math>\nerreicht ihn im sichtbaren Winkelbereich. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mi>λ<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d=\\lambda/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\beta=0<\/annotation><\/semantics><\/math>\nliegt das Maximum quer zur Achse bei 90°, die Nullstellen an den Polen.\nMit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\beta=\\pi<\/annotation><\/semantics><\/math>\nliegt das Maximum an den Polen und die Nullstelle quer zur Achse. Das\nModell setzt vorgegebene Ströme, keine gegenseitige Kopplung und\nidentische Elementdiagramme voraus. Reale Dipole können eine durch den\nArrayfaktor gewünschte Richtung aufgrund ihrer eigenen Nullstelle\ndennoch nicht sinnvoll bedienen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_064_DE.svg\"\nalt=\"Normierte Dipol- und Array-Leistungsdiagramme für zwei isotrope Quellen bei d gleich halber Wellenlänge und zwei Phasenlagen.\" />\n<figcaption>Abbildung: Dipolmodelle und ein Array aus zwei idealen\nStrahlern liefern unterschiedliche Richtdiagramme; bei einem Abstand von\neiner halben Wellenlänge verschiebt die relative Phase die\nHauptkeulen.<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Entwurfsgrenzen<\/h2>\n<p>Bei 2,4 GHz ist ein halber idealisierter Wellenlängenabstand rund\n6,25 cm. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\beta=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>60<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=60^\\circ<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mi>d<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">kd\\cos\\theta=\\pi/2<\/annotation><\/semantics><\/math>;\ndaraus folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">F_n=0{,}5<\/annotation><\/semantics><\/math>.\nFür ein gleichphasiges Zweierarray mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mi>λ<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d=\\lambda/2<\/annotation><\/semantics><\/math>\nergibt die Integration des normierten Leistungsdiagramms\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">Ω<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega_A=2\\pi<\/annotation><\/semantics><\/math>\nund damit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">D_0=2<\/annotation><\/semantics><\/math>\n(3,01 dBi). Das ist nicht 6 dBi, obwohl die Feldsumme im Maximum\ngegenüber einem einzelnen gleich stark erregten Element doppelt und die\nlokale Leistungsdichte vierfach ist: Die Gesamtleistung ist unter der\ngewählten idealen Geometrie doppelt.<\/p>\n<p>Bei einer Fläche von 0,1 m² und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>η<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\eta_a=0{,}6<\/annotation><\/semantics><\/math>\nergibt sich bei 2,4 GHz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>G<\/mi><mo>≈<\/mo><mn>48<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">G\\approx48{,}3<\/annotation><\/semantics><\/math>,\nalso etwa 16,84 dBi. Dieser vereinfachte Aperturwert ersetzt keine\nelektromagnetische Simulation und keine Messung von Impedanz oder\nDiagramm. Größere Abstände in Arrays können weitere gleich starke Maxima\nerzeugen; reale Speisenetze verursachen Verluste und Phasenfehler.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Übungen mit Lösungen<\/h2>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bei 2,4 GHz: Bestimme die idealisierte Halbwellenlänge.\n<strong>Lösung:<\/strong> etwa 6,25 cm.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mi>λ<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d=\\lambda/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\beta=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>90<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=90^\\circ<\/annotation><\/semantics><\/math>.\n<strong>Lösung:<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">F_n=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Gleiche Geometrie,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β<\/mi><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\beta=\\pi<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><msup><mn>90<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\theta=90^\\circ<\/annotation><\/semantics><\/math>.\n<strong>Lösung:<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">F_n=0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Warum sind 6 dB höhere lokale Leistung nicht automatisch 6 dBi\nRichtwirkung? <strong>Lösung:<\/strong> Auch die gesamte abgestrahlte\nLeistung und deren Winkelverteilung müssen berücksichtigt werden.<\/div><\/li>\n<\/ol>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://opencourses.emu.edu.tr/course/view.php?id=395\">Eastern\nMediterranean University – EENG463 Antenna Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Linear Wire\nAntennas, Linear Arrays und Aperture Antennas: Dipole, Gruppen und\nAperturen. Kursübersicht, PDF nicht geprüft. · Zuletzt abgerufen:\n2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://vtechworks.lib.vt.edu/bitstream/handle/10919/93253/Electromagnetics_Vol2_screen-reader-friendly.pdf\">Steven\nW. Ellingson – Electromagnetics, Volume 2 (2020, VT Publishing, PDF)<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a>\n· § 9.5, § 9.7 und § 10.13: Dipolstrahlung und effektive Apertur;\nArrayfaktor nicht durch diesen Beleg abgesichert. · Zuletzt abgerufen:\n2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M17-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M17-L4 – Anpassung und Ausbreitung<\/h1>\n<p><strong>Kursbereich:<\/strong> M17 – Bachelor: Antennen<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlbereich<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M17&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M17-L2<\/a>, <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M1&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L6<\/a>, <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M4&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M4-L1<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Reflexion, Polarisationsverluste und\nFreiraumdämpfung getrennt berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Anschluss und Reflexion<\/h2>\n<p>Eine Antenne hat am Speisepunkt eine komplexe Eingangsimpedanz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><msub><mi>R<\/mi><mi>A<\/mi><\/msub><mo>+<\/mo><mi>j<\/mi><msub><mi>X<\/mi><mi>A<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Z_A=R_A+jX_A<\/annotation><\/semantics><\/math>.\nAuf einer verlustfreien Leitung mit reeller Bezugsimpedanz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>Z<\/mi><mi>c<\/mi><\/msub><annotation encoding=\"application/x-tex\">Z_c<\/annotation><\/semantics><\/math>\nergibt sich<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mo>=<\/mo><mfrac><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>−<\/mo><msub><mi>Z<\/mi><mi>c<\/mi><\/msub><\/mrow><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>+<\/mo><msub><mi>Z<\/mi><mi>c<\/mi><\/msub><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"1.0em\"><\/mspace><msub><mi>P<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><msub><mi>P<\/mi><mo>+<\/mo><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Γ<\/mi><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma=\\frac{Z_A-Z_c}{Z_A+Z_c},\\quad P_a=P_+(1-|\\Gamma|^2).<\/annotation><\/semantics><\/math><\/p>\n<p><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mo>+<\/mo><\/msub><annotation encoding=\"application/x-tex\">P_+<\/annotation><\/semantics><\/math>\nbezeichnet die am Bezugspunkt hinlaufende Leistung. Das\nStehwellenverhältnis ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mi>W<\/mi><mi>R<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">SWR=(1+|\\Gamma|)/(1-|\\Gamma|)<\/annotation><\/semantics><\/math>\nund der positive Rückflussdämpfungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mi>L<\/mi><mo>=<\/mo><mi>−<\/mi><mn>20<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Γ<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">RL=-20\\log_{10}|\\Gamma|<\/annotation><\/semantics><\/math>.\nIn einer Messung wird dagegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>S<\/mi><mn>11<\/mn><\/msub><annotation encoding=\"application/x-tex\">S_{11}<\/annotation><\/semantics><\/math>\nhäufig als negativer dB-Wert dargestellt. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><mn>100<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_A=100\\,\\Omega<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>c<\/mi><\/msub><mo>=<\/mo><mn>50<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_c=50\\,\\Omega<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma=1/3<\/annotation><\/semantics><\/math>,\nSWR 2, RL 9,54 dB. 11,11 % der hinlaufenden Leistung werden reflektiert,\ndie Fehlanpassungsdämpfung beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>10<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>8<\/mn><mi>/<\/mi><mn>9<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>512<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-10\\log_{10}(8/9)=0{,}512<\/annotation><\/semantics><\/math>\ndB. Eine gut angepasste Antenne kann trotzdem ineffizient sein: Ein\nAbschlusswiderstand kann perfekt angepasst sein und wandelt die Leistung\nüberwiegend in Wärme um.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Empfang und Polarisation<\/h2>\n<p>Bei passender Polarisation und konjugierter Lastanpassung entsteht\naus der einfallenden Flussdichte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>S<\/mi><annotation encoding=\"application/x-tex\">S<\/annotation><\/semantics><\/math>\ndie verfügbare Empfangsleistung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><mi>S<\/mi><msub><mi>A<\/mi><mi>e<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">P_r=S A_e<\/annotation><\/semantics><\/math>.\nFür zwei linear polarisierte Antennen mit Drehwinkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ψ<\/mi><annotation encoding=\"application/x-tex\">\\psi<\/annotation><\/semantics><\/math>\nihrer Polarisationsrichtungen (bei gleicher Ausbreitungsachse) kommt der\nLeistungsfaktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mi>ψ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">p=\\cos^2\\psi<\/annotation><\/semantics><\/math>\nhinzu. Dieser Faktor betrifft die Feldprojektion, nicht automatisch das\ngeometrische Richtdiagramm. Bei 45° beträgt die Einbuße 3,01 dB, bei 60°\n6,02 dB. Bei 90° entsteht im Idealmodell eine Nullstelle; reale Antennen\nund Mehrwegeausbreitung können eine endliche Kopplung verursachen.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Friis-Gleichung<\/h2>\n<p>Kombinieren wir\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><msub><mi>P<\/mi><mi>t<\/mi><\/msub><msub><mi>G<\/mi><mi>t<\/mi><\/msub><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>π<\/mi><msup><mi>r<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S=P_tG_t/(4\\pi r^2)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>A<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><msup><mi>λ<\/mi><mn>2<\/mn><\/msup><msub><mi>G<\/mi><mi>r<\/mi><\/msub><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A_e=\\lambda^2G_r/(4\\pi)<\/annotation><\/semantics><\/math>,\nfolgt im Freiraum<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><msub><mi>P<\/mi><mi>t<\/mi><\/msub><msub><mi>G<\/mi><mi>t<\/mi><\/msub><msub><mi>G<\/mi><mi>r<\/mi><\/msub><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mi>λ<\/mi><mrow><mn>4<\/mn><mi>π<\/mi><mi>r<\/mi><\/mrow><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_r=P_t G_t G_r\\left(\\frac{\\lambda}{4\\pi r}\\right)^2.<\/annotation><\/semantics><\/math><\/p>\n<p>Hier ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>t<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_t<\/annotation><\/semantics><\/math>\ndie angenommene Sendeleistung und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>r<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_r<\/annotation><\/semantics><\/math>\ndie verfügbare Empfangsleistung bei passender Polarisation. Die\nsogenannte Freiraumdämpfung ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">S<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>20<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><mi>π<\/mi><mi>r<\/mi><mi>/<\/mi><mi>λ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">L_\\mathrm{FS}=20\\log_{10}(4\\pi r/\\lambda)<\/annotation><\/semantics><\/math>\nin dB. Mit Entfernung in km und Frequenz in MHz gilt näherungsweise\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>L<\/mi><mrow><mi mathvariant=\"normal\">F<\/mi><mi mathvariant=\"normal\">S<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>32<\/mn><mo>,<\/mo><mn>45<\/mn><mo>+<\/mo><mn>20<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><msub><mi>r<\/mi><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/msub><mo>+<\/mo><mn>20<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><msub><mi>f<\/mi><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">L_\\mathrm{FS}=32{,}45+20\\log_{10}r_\\mathrm{km}+20\\log_{10}f_\\mathrm{MHz}<\/annotation><\/semantics><\/math>.\nBei 2,4 GHz und 1 km ergeben sich 100,05 dB. Bei doppelter Entfernung\nsteigen die Verluste um 6,02 dB. Doppelte Frequenz erhöht die isotrope\nFreiraumdämpfung ebenfalls um 6,02 dB; bei konstanten physischen\nEmpfangsaperturen kann sich gleichzeitig der Gewinn ändern. Der\nVergleich muss also seine festen Größen benennen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_065_DE.svg\"\nalt=\"Reflektierter Leistungsanteil für reelle Lasten, Polarisationseinbuße und Freiraumdämpfung bei zwei Frequenzen.\" />\n<figcaption>Abbildung: Fehlanpassung am reellen Abschluss, verdrehte\nPolarisation und Freiraumdämpfung beeinflussen ein Linkbudget über\nverschiedene Mechanismen, die nicht als derselbe Verlustfaktor behandelt\nwerden dürfen.<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Terrestrische Ausbreitung und Fresnel-Zone<\/h2>\n<p>Für die erste Fresnel-Zone gilt näherungsweise\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><msqrt><mrow><mi>λ<\/mi><msub><mi>d<\/mi><mn>1<\/mn><\/msub><msub><mi>d<\/mi><mn>2<\/mn><\/msub><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>d<\/mi><mn>1<\/mn><\/msub><mo>+<\/mo><msub><mi>d<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">r_1=\\sqrt{\\lambda d_1d_2/(d_1+d_2)}<\/annotation><\/semantics><\/math>.\nBei jeweils 500 m Teilstrecke und 2,4 GHz ist der Radius 5,59 m. Auch\nbei geometrischer Sicht können Hindernisse innerhalb dieser Zone die\nEmpfangsleistung beeinflussen. Die Fresnel-Zone ist von der\nFresnel-Nahfeldregion einer einzelnen Antenne zu unterscheiden.\nBodenreflexion, Vegetation, Gebäude, Erdkrümmung und atmosphärische\nRefraktion ändern die tatsächliche Übertragung. Freiraumdämpfung ist\ndeshalb eine Referenz, kein Garant für eine bestimmte Feldstärke oder\nVerfügbarkeit. Ein Mehrwegekanal kann sowohl konstruktive als auch\ndestruktive Überlagerung erzeugen. Eine pauschale Zusatzdämpfung ist nur\nein Sensitivitätsszenario, kein physikalisch begründeter\nMehrwegekanal.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Übungen mit Lösungen<\/h2>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>A<\/mi><\/msub><mo>=<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_A=25\\,\\Omega<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>c<\/mi><\/msub><mo>=<\/mo><mn>50<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_c=50\\,\\Omega<\/annotation><\/semantics><\/math>.\n<strong>Lösung:<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma=-1/3<\/annotation><\/semantics><\/math>,\nSWR 2, 11,11 % Reflexionsleistung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Dämpfung entsteht bei 30° Polarisationsoffset?\n<strong>Lösung:<\/strong>\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>10<\/mn><msub><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><mn>10<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>75<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>25<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-10\\log_{10}(0{,}75)=1{,}25<\/annotation><\/semantics><\/math>\ndB.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Verzehnfache r bei unveränderter Frequenz. <strong>Lösung:<\/strong>\n+20 dB Freiraumdämpfung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Ist eine freie Sichtlinie ausreichend für das Friis-Modell?\n<strong>Lösung:<\/strong> Nein, Mehrwegeeffekte und Hindernisse in der\nFresnel-Zone können die Rechnung verändern.<\/div><\/li>\n<\/ol>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://opencourses.emu.edu.tr/course/view.php?id=395\">Eastern\nMediterranean University – EENG463 Antenna Theory<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fundamental\nParameters of Antennas-1/-2: Eingangsimpedanz, effektive Apertur und\nFriis-Gleichung. Kursübersicht, PDF nicht geprüft. · Zuletzt abgerufen:\n2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.itu.int/rec/R-REC-P.525-5-202411-I/en\">ITU-R\nP.525-5 – Calculation of free-space attenuation (11/2024)<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · ITU-R\nP.525-5 (11/2024), Anhang §2.3, S. 3, Gl. (5)–(6): Freiraumdämpfung;\nPDF-Text geprüft, Seitenansicht nicht abrufbar. · Zuletzt abgerufen:\n2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>"};
